from solution import house_bowling


def test_zeros():
    assert house_bowling([0] * 20) == 0


def test_single_strike_first():
    assert house_bowling([10] + [0] * 18) == 10


def test_all_strikes():
    # 9 frames + 10th strike (one roll): 10 rolls of 10
    # frames 1-8: 30 each = 240; frame 9: 10+10=20; frame 10: 10
    assert house_bowling([10] * 10) == 270


def test_tenth_strike_only_ten():
    rolls = [0] * 18 + [10]
    assert house_bowling(rolls) == 10


def test_ninth_strike_tenth_strike():
    rolls = [0] * 16 + [10, 10]
    assert house_bowling(rolls) == 30


def test_ninth_strike_tenth_open():
    rolls = [0] * 16 + [10, 3, 4]
    assert house_bowling(rolls) == 17 + 7


def test_tenth_spare_no_bonus():
    rolls = [0] * 18 + [5, 5]
    assert house_bowling(rolls) == 10


def test_ninth_spare_tenth_strike():
    rolls = [0] * 16 + [4, 6, 10]
    assert house_bowling(rolls) == 20 + 10


def test_all_fives_spares():
    # 9 frames spares: each 10+5 = 15 -> 135; frame 10: 5+5=10
    rolls = [5] * 20
    assert house_bowling(rolls) == 145


