def test_valid_mixed():
    rolls = [10, 7, 3, 9, 0, 10, 0, 8, 8, 2, 0, 6, 10, 10, 10, 8, 1][:0] or \
        [10, 7, 3, 9, 0, 10, 0, 8, 8, 2, 0, 6, 10, 10, 10, 10]
    # f1 20; f2 19; f3 9; f4 18; f5 8; f6 10+0=10; f7 6; f8 30; f9 20; f10 10
    assert house_bowling(rolls) == 20 + 19 + 9 + 18 + 8 + 10 + 6 + 30 + 20 + 10


def test_strike_then_spare_early():
    rolls = [10, 5, 5, 3] + [0] * 14
    # f1: 10+5+5=20; f2 spare 5,5 +3=13; f3: 3
    assert house_bowling(rolls) == 36
